INSERT OR REPLACE INTO WebsiteContents (Key, DataJson, UpdatedAt)
VALUES ('about', '{"data":{"hero":{"title":"About Us","image":"https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&q=80&w=2000","subtitle":"Efficacious is synonymous with Efficiency. Providing innovative & efficient solutions to make life Safe, Secure & Easy."},"vision":{"points":["Global Reach","Technological Innovation","User-Centric Design"],"title":"Our Vision","content":"To be the global leader in providing innovative and efficient ERP solutions that set new standards in user experience and operational excellence."},"mission":{"points":["Child Security First","Operational Efficiency","Scalable Solutions"],"content":"Our mission is to make life Safe, Secure & Easy through technology. We strive to empower educational institutions and businesses with tools that simplify complexity.","title":"Our Mission"},"whoWeAre":{"image":"https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&q=80&w=800","yearsExperience":"10+","title":"Who We Are","content":["Incorporated in 2012 by Mr. Kamal Agrawal, a core finance professional, we started with a vision to create innovative IT solutions for selective target segments.","While we began with IT outsourcing, today Efficacious focuses on creating complete ERP solutions for schools and education institutes. Our mission is to revolutionize school operations with Child Security as the prime focus.","We are a team of dedicated professionals committed to delivering high-quality, scalable, and secure software solutions that empower businesses and institutions to thrive in the digital age."]},"values":[{"id":1,"title":"Innovation","description":"Constantly pushing boundaries to create better solutions."},{"title":"Integrity","id":2,"description":"Building trust through transparency and ethical practices."},{"title":"Excellence","id":3,"description":"Striving for the highest quality in everything we do."},{"id":4,"description":"Ensuring the safety and privacy of data for all users.","title":"Security"}]}}', '2026-10-30T11:02:20.919Z');
