INSERT OR REPLACE INTO WebsiteContents (Key, DataJson, UpdatedAt)
VALUES ('careers', '{"data":[{"criteria":["3 to 4 years of ERP Sales Experience","MBA (Marketing)"],"title":"Sales & Business Development","department":"Software / IT Solutions","id":1,"type":"Full Time","description":"<div><b>About the Role:</b></div><div>We are looking for a dynamic, result-oriented, and self-motivated Business Development Executive to drive sales and acquire new clients for our software products and IT solutions.</div><div>Our product portfolio includes E-Smart School Management Software, E-Smart Health Management Software, E-Smart Queue Management System, and E-Smart Restaurant Management Software, along with their respective mobile applications.</div><div>The candidate will be responsible for identifying potential customers, generating business leads, conducting product demonstrations, building client relationships, and converting prospects into long-term customers.</div><div><br></div><div><b>Key Responsibilities:</b></div><ul><li><i>Identify and generate new business opportunities across relevant industries.</i></li><li><i>Research and approach potential clients, including schools, colleges, hospitals, clinics, restaurants, and other businesses.</i></li><li><i>Generate leads through cold calling, email marketing, LinkedIn, networking, referrals, and other channels.</i></li><li><i>Understand client requirements and recommend suitable software solutions.</i></li><li><i>Schedule and conduct product demonstrations and presentations for prospective clients.</i></li><li><i>Develop and maintain strong relationships with prospective and existing customers.</i></li><li><i>Prepare sales proposals, quotations, and presentations in coordination with the concerned team.</i></li><li><i>Follow up with potential clients, negotiate commercial terms, and close sales deals.</i></li><li><i>Maintain an updated database of leads, prospects, meetings, and sales activities in the CRM or reporting system.</i></li><li><i>Achieve monthly and quarterly lead generation, client acquisition, and revenue targets.</i></li><li><i>Coordinate with the technical and implementation teams to ensure a smooth customer onboarding process.</i></li><li><i>Monitor market trends, competitor offerings, and customer feedback to identify new business opportunities.</i><br><br></li></ul><div><b>Required Skills and Qualifications:</b></div><ul><li><i>Bachelor''s degree in Business Administration, Marketing, Sales, IT, or a related field.</i></li><li><i>1–3 years of experience in business development, B2B sales, or IT/software sales is preferred.</i></li><li><i>Excellent verbal and written communication skills.</i></li><li><i>Strong negotiation, presentation, and convincing skills.</i></li><li><i>Experience in lead generation, prospecting, and client acquisition.</i></li><li><i>Basic understanding of software products, web applications, and mobile applications.</i></li><li><i>Ability to understand customer requirements and present suitable solutions.</i></li><li><i>Good relationship-building and follow-up skills.</i></li><li><i>Ability to work independently and achieve sales targets.</i></li><li><i>Proficiency in MS Office, email communication, and online business tools.</i><br><br></li></ul><div><b>Preferred Qualifications:</b></div><ul><li><i>Experience selling software products, SaaS solutions, or IT services.</i></li><li><i>Experience in selling software to educational institutions, healthcare organizations, restaurants, or other businesses.</i></li><li><i>Familiarity with CRM tools, LinkedIn prospecting, and digital lead-generation techniques.</i></li><li><i>A proven track record of acquiring new clients and closing B2B sales</i>.<br><br></li></ul><div>Key Performance Indicators (KPIs)<br><br></div><div><b>Performance will be evaluated based on:</b></div><ul><li><i>Number of qualified leads generated.</i></li><li><i>Number of client meetings and product demonstrations conducted.</i></li><li><i>Number of new clients acquired.</i></li><li><i>Conversion rate from leads to paying customers.</i></li><li><i>Monthly and quarterly sales revenue achieved.</i></li><li><i>Quality of client relationships and follow-up activities.</i><br><br></li></ul><div><b>Ideal Candidate:</b></div><div>The ideal candidate should be proactive, confident, persuasive, and passionate about sales. They should have a strong business mindset, the ability to communicate with decision-makers, and the motivation to generate new business opportunities for our software products.<br><br></div><b>Work Location: </b>In person","experience":"1–3 Years (Preferred)","location":"Mumbai (On-site)"},{"description":"<div><b>Job Description:</b></div><div>We are looking for a detail-oriented and organized Back Office Executive to handle day-to-day administrative work, data entry, documentation, and basic accounting-related activities. Candidates with knowledge of Tally and basic accounting will be preferred.<br><br></div><div><b>Key Responsibilities:</b></div><ul><li><i>Perform daily data entry and maintain accurate records.</i></li><li><i>Handle invoices, bills, vouchers, and other business documents.</i></li><li><i>Maintain and update Excel sheets, reports, and databases.</i></li><li><i>Assist with basic accounting and financial record-keeping.</i></li><li><i>Manage filing, documentation, and office administration.</i></li><li><i>Coordinate with internal departments for routine office tasks.</i></li><li><i>Maintain records of sales, purchases, payments, and receipts</i>.<br><br></li></ul><div><b>Required Skills:</b></div><ul><li><i>Basic computer knowledge, including MS Excel and MS Word.</i></li><li><i>Good typing speed and attention to detail.</i></li><li><i>Good communication and organizational skills.</i></li><li><i>Ability to maintain records accurately and meet deadlines.</i></li><li><i>Knowledge of Tally is an added advantage.</i></li><li><i>Basic accounting knowledge will be preferred.<br><br></i></li></ul><div><b>Eligibility</b></div><ul><li><i>Freshers and experienced candidates can apply.</i></li><li><i>Candidates with Tally knowledge and accounting experience will be given preference.<br><br></i></li></ul><div><b>Education:</b></div><ul><li><i>Bachelor''s (Preferred)<br></i></li></ul>","department":" Fresher / Experienced","location":"Navi Mumbai (On-site)","id":1793186718674,"experience":"1–3 Years (Preferred)","criteria":["Work Location: In person"],"title":"Administration / Back Office","type":"Full Time"}]}', '2026-10-30T11:02:20.919Z');
