INSERT OR REPLACE INTO WebsiteContents (Key, DataJson, UpdatedAt)
VALUES ('products', '{"data":[{"newTab":true,"href":"/products/esmart-school","heroTitle":"Smart Management for Modern Schools","title":"eSmart School","features":[{"description":"A comprehensive view for parents, teachers, and admins. Get real-time updates on attendance, circulars, and academic progress at a glance.","details":["Real-time Notifications","Daily Event Summary","Quick Action Shortcuts"],"color":"bg-blue-500","iconName":"Monitor","id":10,"textAccent":"text-blue-600","title":"Centralized Dashboard"},{"id":11,"color":"bg-green-500","description":"Say goodbye to manual registers. Teachers can mark attendance via the app, triggering instant notifications to parents for absentees.","iconName":"Calendar","details":["Instant Parent Alerts","Monthly Reports","Leave Management"],"title":"Smart Attendance","textAccent":"text-green-600"},{"details":["Secure Gateway","Auto-Receipt Generation","Due Date Reminders"],"textAccent":"text-orange-600","title":"Fee Management","iconName":"CreditCard","id":12,"description":"Automated fee reminders and secure online payment gateway. Parents can view invoices, pay fees, and download receipts instantly.","color":"bg-orange-500"},{"description":"Easy creation and submission of assignments. Teachers can post homework, study materials, and assignments directly, and students can submit their work online.","details":["Digital Homework Submissions","Attachment Uploads (PDFs/Images)","Teacher Grading & Feedback"],"textAccent":"text-purple-600","iconName":"BookOpen","color":"bg-purple-500","id":13,"title":"Homework & Assignments"},{"description":"Detailed performance reports and analytics. Visualize student progress over time with graphical representations of grades.","details":["Performance Graphs","Term-wise Comparison","Downloadable Report Cards"],"textAccent":"text-red-600","iconName":"BarChart3","title":"Result & Analysis","id":14,"color":"bg-red-500"}],"modules":[{"iconName":"Users","title":"Admission Management"},{"title":"Library Management","iconName":"Library"},{"iconName":"Users","title":"HR & Payroll"},{"title":"Inventory","iconName":"FileText"},{"iconName":"BookOpen","title":"Homework & Assignments"},{"iconName":"Bell","title":"Communication Center"}],"description":"A complete ERP solution for schools & educational institutes.","heroSubtitle":"A complete ecosystem that connects parents, teachers, and students. Streamline operations while keeping child security as the prime focus.","gradient":"from-blue-400 via-indigo-500 to-purple-600","textAccent":"text-blue-600 dark:text-blue-400","comingSoon":false,"id":1,"bgAccent":"bg-blue-500/10","playStoreLink":"https://play.google.com/store/apps/details?id=net.esmarts.app.esmart&hl=en_IN","enabled":true,"iconName":"GraduationCap","stats":[{"label":"Schools Onboarded","value":"500+"},{"value":"1M+","label":"Parents Connected"},{"label":"Uptime Guaranteed","value":"99.9%"}],"appStoreLink":"https://apps.apple.com/in/app/e-smart-school/id6448924052"},{"features":[{"color":"bg-emerald-500","iconName":"FolderHeart","id":3,"description":"Securely store, organize, and manage medical records—including lab reports, vaccination certificates, prescriptions, and hospital visits—in one safe, unified digital vault.","title":"Your Health Manager","textAccent":"text-emerald-600","details":["Secure PDF/Image Uploads","Categorized Diagnostic Reports","Digital Prescriptions Log"]},{"textAccent":"text-teal-600","color":"bg-teal-500","description":"Track doctor visits, follow complex prescription schedules, set timely medication pill reminders, and manage overall wellness for your family.","id":40,"iconName":"Clock","title":"Manage Health & Prescriptions","details":["Smart Pill Reminders","Doctor Visit Schedules","Adherence Tracking"]}],"description":"Your secure personal health manager. Store medical records, track prescriptions, and find trusted healthcare providers nearby.","enabled":true,"title":"eSmart Health","appStoreLink":"https://apps.apple.com/in/app/e-smart-health/id6756566627","modules":[{"title":"Health Records","iconName":"FolderHeart"},{"iconName":"Bell","title":"Pill Reminders"},{"iconName":"Search","title":"Care Search"}],"stats":[{"value":"100%","label":"Secure Storage"},{"label":"Specialties Covered","value":"10+"},{"label":"Health Records Access","value":"24/7"}],"gradient":"from-emerald-400 via-teal-500 to-cyan-600","id":2,"comingSoon":false,"bgAccent":"bg-emerald-500/10","playStoreLink":"https://play.google.com/store/apps/details?id=com.efficacious.esmarthealth&hl=en","iconName":"Activity","textAccent":"text-emerald-600 dark:text-emerald-400","href":"/products/esmart-health","newTab":true},{"appStoreLink":"https://apps.apple.com/co/app/e-smart-restaurant/id6762969059?l=en-GB","modules":[{"iconName":"Layers","title":"Table Reservation"},{"title":"Waitlist Management","iconName":"Coffee"},{"title":"Billing & POS","iconName":"CreditCard"}],"playStoreLink":"https://play.google.com/store/apps/details?id=com.efficacious.new_esmartrestaurant","textAccent":"text-rose-600 dark:text-rose-400","description":"Digitize your restaurant operations from kitchen to customer. Enhance service speed, reduce wastage, and increase profitability.","stats":[{"label":"Table Turnover","value":"+30%"},{"value":"15%","label":"Food Cost Reduction"},{"label":"Order Errors","value":"0%"}],"features":[{"textAccent":"text-rose-600","title":"Digital Menu & Ordering","iconName":"QrCode","description":"Provide a seamless contactless experience. Customers can scan QR codes to view vivid menus and place orders directly.","details":["Contactless Ordering","Dynamic Menu Updates","Upselling Prompts"],"id":40,"color":"bg-rose-500"},{"color":"bg-orange-500","iconName":"Monitor","textAccent":"text-orange-600","title":"Kitchen Display System","description":"Streamline your kitchen operations. Replace noisy printers with smart screens that route orders to specific stations.","details":["Station-wise Routing","Color-coded Status","Prep Time Tracking"],"id":41}],"comingSoon":false,"bgAccent":"bg-rose-500/10","title":"eSmart Restaurant","iconName":"Utensils","gradient":"from-rose-400 via-pink-500 to-orange-600","newTab":true,"enabled":true,"href":"/products/esmart-restaurant","id":3},{"heroSubtitle":"A next-generation slot-booking platform that connects citizens to any service provider, replacing waiting lines with mobile bookings and contactless QR-code entry.","enabled":true,"comingSoon":false,"textAccent":"text-violet-600 dark:text-violet-400","features":[{"iconName":"Calendar","id":50,"color":"bg-violet-600","textAccent":"text-violet-600","description":"End users select date, time, and service provider from the mobile app. Instant availability check and confirmation in under 60 seconds.","title":"Smart Slot Booking","details":["Date & Time Selection","Real-time Availability","Instant Confirmation"]},{"iconName":"QrCode","title":"QR Code Entry Pass","textAccent":"text-indigo-600","details":["Encrypted QR Generation","Tap-to-Show on Mobile","Contactless Entry"],"description":"A unique encrypted QR code is generated on slot confirmation. Users present it at the entry scanner for contactless, queue-free access.","id":51,"color":"bg-indigo-600"}],"appStoreLink":"https://apps.apple.com/ph/app/e-smart-queue/id6784201811","id":4,"stats":[{"value":"70%","label":"Wait Time Reduction"},{"value":"50+","label":"Service Categories"},{"value":"Zero","label":"Physical Queues"}],"description":"Eliminate physical queues with smart slot booking and QR-based entry for banks, hospitals, post offices, temples, and more.","href":"/products/esmart-queue","iconName":"Timer","title":"eSmart Queue","bgAccent":"bg-violet-500/10","newTab":true,"playStoreLink":"https://play.google.com/store/apps/details?id=com.efficacious.esmartqueue","modules":[{"iconName":"Smartphone","title":"User Mobile App"},{"iconName":"BarChart3","title":"Admin Dashboard"},{"title":"QR Scanner Portal","iconName":"QrCode"},{"iconName":"Bell","title":"Push Notifications"},{"iconName":"TrendingUp","title":"Analytics"},{"iconName":"Building2","title":"Multi-branch"}],"gradient":"from-violet-400 via-fuchsia-500 to-pink-600","heroTitle":"End Queues. Start Living."}]}', '2026-10-30T11:02:20.919Z');
